    let claims = Claims::new(
        "bench-runner".to_string(),
        format!("{}-issuer", ID_PREFIX),
        format!("{}-audience", ID_PREFIX),
        now + 3600, // exp: 1 hour
        now,        // iat: now
    )
    .with_scope(format!("udex:entry:v1:{}:**", index_name));

